#include <iostream>
#include <cmath>

bool redondear_entero(double origen, int& destino) {
    if (!std::isfinite(origen) || origen < -100.0 || origen > 100.0) {
        return false;
    }
    const double candidato = std::round(origen);
    destino = static_cast<int>(candidato);
    return true;
}

int main() {
    int destino{28};
    double origen{2.25};
    bool aceptado = redondear_entero(origen, destino);
    std::cout << "Cercano positivo: " << aceptado << ";Destino: " << destino << '\n';
    origen = -2.75;
    aceptado = redondear_entero(origen, destino);
    std::cout << "Cercano negativo: " << aceptado << ";Destino: " << destino << '\n';
    origen = 4.5;
    aceptado = redondear_entero(origen, destino);
    std::cout << "Mitad positiva: " << aceptado << ";Destino: " << destino << '\n';
    origen = -4.5;
    aceptado = redondear_entero(origen, destino);
    std::cout << "Mitad negativa: " << aceptado << ";Destino: " << destino << '\n';
    origen = 100.0;
    aceptado = redondear_entero(origen, destino);
    std::cout << "Frontera: " << aceptado << ";Destino: " << destino << '\n';
    origen = 100.25;
