#include <iostream>
#include <cmath>

bool convertir_entero(double origen, int& destino) {
    if (!std::isfinite(origen) || origen < -100.0 || origen > 100.0) {
        return false;
    }
    const int candidato = static_cast<int>(origen);
    if (static_cast<double>(candidato) != origen) {
        return false;
    }
    destino = candidato;
    return true;
}

bool redondear_entero(double origen, int& destino) {
    if (!std::isfinite(origen) || origen < -100.0 || origen > 100.0) {
        return false;
    }
    const double candidato = std::round(origen);
    destino = static_cast<int>(candidato);
    return true;
}

int main() {
    int piezas{9};
    int marca{9};
    bool exacto = convertir_entero(4.75, piezas);
    bool cercano = redondear_entero(4.75, marca);
    std::cout << "Fraccion: " << exacto << ':' << piezas << '|' << cercano << ':' << marca << '\n';
    exacto = convertir_entero(0.0, piezas);
    cercano = redondear_entero(0.0, marca);
    std::cout << "Cero: " << exacto << ':' << piezas << '|' << cercano << ':' << marca << '\n';
    exacto = convertir_entero(-100.25, piezas);
    cercano = redondear_entero(-100.25, marca);
    std::cout << "Fuera: " << exacto << ':' << piezas << '|' << cercano << ':' << marca;
    return 0;
}

