#include <iostream>
#include <cmath>
#include <vector>

bool redondear_entero(double origen, int& destino) {
    if (!std::isfinite(origen) || origen < -100.0 || origen > 100.0) {
        return false;
    }
    const double candidato = std::round(origen);
    destino = static_cast<int>(candidato);
    return true;
}

int main() {
    const std::vector<double> datos{1.25, 1.75, 2.0, -1.75, 101.0, 0.0, -0.4, 1.25};
    const std::vector<double> original = datos;
    std::vector<int> marcas;
    int colisiones{0};
    int rechazados{0};
    for (const double origen : datos) {
        int marca{71};
        if (!redondear_entero(origen, marca)) {
            ++rechazados;
        } else {
            bool encontrada{false};
            for (const int existente : marcas) {
                if (existente == marca) {
                    encontrada = true;
                    break;
                }
            }
            if (encontrada) {
                ++colisiones;
            } else {
                marcas.push_back(marca);
            }
        }
    }
    std::cout << "Marcas:";
    for (const int marca : marcas) {
        std::cout << ' ' << marca;
    }
    std::cout << "\nColisiones: " << colisiones
              << "\nRechazados: " << rechazados
              << "\nDatos conservados: " << (datos == original) << '\n';
    return 0;
}

